function HamghadamSupportUrl(value, platform) {
  try {
    const url = new URL(value);
    if (url.protocol !== 'https:' || url.username || url.password || url.port) return null;
    if (platform === 'rubika') {
      return url.hostname === 'rubika.ir' && url.pathname === '/CustomerSupportAdmin' && !url.search && !url.hash ? url.href : null;
    }
    return (url.hostname === 'linkedin.com' || url.hostname === 'www.linkedin.com') && /^\/(in|company)\/[^/]+\/?$/.test(url.pathname) ? url.href : null;
  } catch { return null; }
}

async function HamghadamCopySupportHandle() {
  const text = HamghadamSupportConfig.rubikaHandle;
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(text);
      return true;
    }
  } catch { /* Local-file or denied clipboard access: try the user-initiated fallback. */ }
  const previousFocus = document.activeElement;
  const field = document.createElement('textarea');
  field.value = text;
  field.readOnly = true;
  field.tabIndex = -1;
  field.setAttribute('aria-label', 'شناسه پشتیبانی برای کپی');
  field.style.cssText = 'position:fixed;top:0;left:0;width:1px;height:1px;opacity:0;font-size:16px;pointer-events:none';
  document.body.appendChild(field);
  let copied = false;
  try {
    field.focus({preventScroll:true});
    field.select();
    field.setSelectionRange(0, text.length);
    copied = document.execCommand('copy');
  } catch { copied = false; }
  finally {
    field.remove();
    previousFocus?.focus({preventScroll:true});
  }
  return copied;
}

