function HamghadamNormalizePhone(value) {
  return value.replace(/[۰-۹]/g, digit => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(digit)))
    .replace(/[٠-٩]/g, digit => String('٠١٢٣٤٥٦٧٨٩'.indexOf(digit)))
    .replace(/[\s()\-]/g, '');
}

function HamghadamValidateCenter(values) {
  const errors = {};
  if (!values.name.trim()) errors.name = 'نام مرکز خدمات پرستاری را وارد کنید.';
  if (!values.phone.trim()) errors.phone = 'شماره تماس مرکز را وارد کنید.';
  else if (!/^(?:0[1-9]\d{9}|(?:\+98|0098)[1-9]\d{9})$/.test(HamghadamNormalizePhone(values.phone)))
    errors.phone = 'شماره تماس معتبر همراه یا ثابت با پیش‌شماره وارد کنید؛ مانند ۰۹۱۲۳۴۵۶۷۸۹ یا ۰۵۱۳۸۴۵۶۷۸۹.';
  if (!values.area.trim()) errors.area = 'شهر یا محدوده فعالیت را وارد کنید.';
  return errors;
}

