  if (!previous || previous.hash !== hash) previous = { hash, requestId: crypto.randomUUID() };
  HamghadamCenterTicket.previous = previous;
  try { sessionStorage.setItem('hamghadam-center-ticket-v1', JSON.stringify(previous)); } catch {}
  return previous.requestId;
